mapper.select:
SELECT mn.*,proj.P_Name AS projectName, user.U_Name AS projectLeaderName, user1.U_Name AS responsiblePersonName, user2.U_Name AS specificContactName FROM group_project_issue mn LEFT JOIN pre_project proj ON proj.P_ID = mn.project_id LEFT JOIN sys_user user ON user.U_ID = mn.project_leader LEFT JOIN sys_user user1 ON user1.U_ID = mn.responsible_person LEFT JOIN sys_user user2 ON user2.U_ID = mn.specific_contact
AND mn.project_id = #{params.projectId}
AND likePname(#{params.projectName},proj.P_Id)=true
AND proj.P_Name LIKE CONCAT('%',#{params.projectName},'%')
AND proj.P_Code LIKE CONCAT('%',#{params.projectCode},'%')
AND user.U_Name LIKE CONCAT('%',#{params.projectLeaderName},'%')
AND mn.project_leader = #{params.projectLeader}
AND mn.responsible_person = #{params.responsiblePerson}
AND user1.U_Name LIKE CONCAT('%',#{params.responsiblePersonName},'%')
AND mn.specific_contact = #{params.specificContact}
AND user2.U_Name LIKE CONCAT('%',#{params.specificContactName},'%')
AND mn.responsible_unit LIKE CONCAT('%',#{params.responsibleUnit},'%')
AND mn.issue_category = #{params.issueCategory}
